  7	internal sealed class DesgloseDeFaltas
  8	{
  9	    private static readonly HashSet<string> Terminos = new(StringComparer.Ordinal)
 10	    {
 11	        "falta", "faltas", "inasistencia", "inasistencias", "asistencia"
 12	    };
 13	
 14	    private readonly PoliticaAcceso _politicaAcceso;
 15	    private readonly IReadOnlyList<AsignaturaCatalogo> _catalogo;
 16	
 17	    public DesgloseDeFaltas(PoliticaAcceso politicaAcceso, IReadOnlyList<AsignaturaCatalogo> catalogo)
 18	    {
 19	        _politicaAcceso = politicaAcceso;
 20	        _catalogo = catalogo;
 21	    }
 22	
 23	    public async Task<string?> PrepararAsync(SesionPregunta sesion, ContextoUsuario contexto, CancellationToken cancellationToken)
 24	    {
 25	        var palabras = TokenizadorTexto.Valores(sesion.Entrada.Pregunta);
 26	        var personaId = palabras.Any(Terminos.Contains) ? PersonaDelDesglose(sesion, contexto, palabras) : null;
 27	        if (personaId is null)
 28	        {
 29	            return null;
 30	        }
 31	
 32	        var resumen = await ResumenDeAsync(sesion, contexto, personaId, cancellationToken);
 33	        var claves = CatalogoAsignaturas.CodigosNombrados(sesion.Entrada.Pregunta, CatalogoAsignaturas.Vigente(_catalogo, sesion.Directorio), sesion.Directorio.CodigosAsignatura);
 34	        return resumen is null ? null : TextoDelDesglose.De(resumen, claves, contexto.Usuario.Rol == Rol.Coordinador);
 35	    }
 36	
 37	    private string? PersonaDelDesglose(SesionPregunta sesion, ContextoUsuario contexto, IReadOnlyList<string> palabras)
 38	    {
 39	        if (contexto.Usuario.Rol == Rol.Estudiante)
 40	        {
 41	            return sesion.Activacion.Entrega ? contexto.Usuario.Id : null;
 42	        }
 43	
 44	        var programas = _politicaAcceso.ProgramasAutorizados(contexto.Usuario, contexto.Directorio);
 45	        var mencionados = ActivadorPrelectura.EstudiantesMencionadosDeSusProgramas(contexto, palabras, programas);
 46	        return mencionados.Count == 1 ? mencionados[0] : null;
 47	    }
 48	
 49	    private async Task<ResumenEstudiante?> ResumenDeAsync(SesionPregunta sesion, ContextoUsuario contexto, string personaId, CancellationToken cancellationToken)
 50	    {
 51	        if (sesion.Registro.Resumenes.TryGetValue(personaId, out var leido))
 52	        {
 53	            return leido;
 54	        }
 55	
 56	        if (!_politicaAcceso.EvaluarLecturaEstudiante(contexto.Usuario, personaId, contexto.Directorio).Permitido)
 57	        {
 58	            return null;
 59	        }
 60	
 61	        var resumen = await ResumenesAcademicos.ResumirAsync(sesion.Api, personaId, cancellationToken);
 62	        Registrar(sesion.Registro, contexto.Directorio, resumen);
 63	        return resumen;
 64	    }
 65	
 66	    private static void Registrar(RegistroConsultas registro, DirectorioAcademico directorio, ResumenEstudiante resumen)
 67	    {
 68	        var programaId = directorio.Estudiantes.First(estudiante => estudiante.Id == resumen.EstudianteId).ProgramaId;
 69	        registro.Registrar(resumen.EstudianteId, [RecursoConsultado.Notas, RecursoConsultado.Asistencia], new Cita(Textos.DocumentoDatosEstudiante, Textos.SeccionAsistencia));
 70	        registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, programaId, RecursoConsultado.Notas, RecursoConsultado.Asistencia));
 71	        registro.RegistrarResumen(resumen);
 72	        registro.RegistrarReglas(ReglasAplicadas.DeNotasYAsistencia([resumen]));
 73	    }
 74	}
 75	using TutorFlow.Core.Academico;
 76	using TutorFlow.Core.Autorizacion;
 77	
 78	namespace TutorFlow.Core.Asistente;
 79	
 80	internal static class TextoDelDesglose
 81	{
 82	    private const string TotalSinRegistro = "Total: sin registro";
 83	
 84	    public static string? De(ResumenEstudiante resumen, IReadOnlyCollection<string> claves, bool terceraPersona)
 85	    {
 86	        var elegidas = resumen.Asignaturas
 87	            .Where(resultado => claves.Count == 0 || claves.Contains(AmbitoPersonal.Clave(resultado.Asignatura.Codigo)))
 88	            .ToList();
 89	        return elegidas.Count == 0
 90	            ? null
 91	            : string.Join("\n", elegidas.Select(resultado => FormateadorDatos.LineaDeAsistencia(resultado, terceraPersona)).Append(Total(elegidas)));
 92	    }
 93	
 94	    private static string Total(IReadOnlyList<ResultadoAsignatura> elegidas)
 95	    {
 96	        var conRegistro = elegidas.Where(resultado => resultado.Asignatura.Asistencia.Inasistencias is not null).ToList();
 97	        var sinRegistro = elegidas.Except(conRegistro).Select(resultado => resultado.Asignatura.Nombre).ToList();
 98	        var faltas = conRegistro.Sum(resultado => resultado.Asignatura.Asistencia.Inasistencias.GetValueOrDefault());
 99	        return conRegistro.Count == 0 ? TotalSinRegistro : $"Total: {faltas} faltas{Complemento(sinRegistro)}";
100	    }
101	
102	    private static string Complemento(List<string> sinRegistro) =>
103	        sinRegistro.Count == 0 ? string.Empty : $" (sin registro: {string.Join(", ", sinRegistro)})";
104	}
105	using System.Text.RegularExpressions;
106	using TutorFlow.Core.Autorizacion;
107	
108	namespace TutorFlow.Core.Asistente;
109	
110	internal static partial class IntroduccionDelDesglose
111	{
112	    public static string SinCifras(string texto) =>
113	        string.Join("\n", SaltoDeLinea().Split(texto).Select(SinOracionesConCifras).OfType<string>()).Trim();
114	
115	    private static string? SinOracionesConCifras(string linea)
116	    {
117	        var conservada = string.Concat(CorteDeOracion().Split(linea).Where(oracion => !TieneCifrasDeFaltas(oracion)));
118	        if (conservada == linea)
119	        {
120	            return linea;
121	        }
122	
123	        return string.IsNullOrWhiteSpace(conservada) ? null : conservada.Trim();
124	    }
125	
126	    private static bool TieneCifrasDeFaltas(string oracion)
127	    {
128	        var normalizada = ComaDecimal.APunto(oracion);
129	        return EnterosDeAsistencia.Candidatos(normalizada, TokenizadorTexto.TokenizarConCifras(normalizada)).Any();
130	    }
131	
132	    [GeneratedRegex(@"\r?\n", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
133	    private static partial Regex SaltoDeLinea();
134	
135	    [GeneratedRegex(@"(?<=[.!?])(?=\s|$)", RegexOptions.CultureInvariant, TiempoLimiteRegex.Milisegundos)]
136	    private static partial Regex CorteDeOracion();
137	}

