149	    [
150	        "enumera", "muestra", "dame", "perdieron", "sacaron", "aprobaron", "reprobaron", "failed", "passed"
151	    ];
152	}
153	namespace TutorFlow.Core.Autorizacion;
154	
155	internal static class ConteoDeExistencia
156	{
157	    private const int MaximoDeRellenoDelConteo = 2;
158	    private const int MaximoEntreVerboYEstado = 2;
159	    private const int SinRelleno = 0;
160	    private const int SinPalabrasEntre = 0;
161	
162	    public static bool Hay(FrasesDelTexto frases) =>
163	        frases.Ocurrencias(VocabularioAgregados.Contadores)
164	            .SelectMany(contador => frases.FinesTrasRelleno(
165	                contador.Fin, VocabularioAgregados.RellenosDelConteo, MaximoDeRellenoDelConteo, VocabularioAgregados.Grupo))
166	            .SelectMany(finDelGrupo => frases.FinesTrasRelleno(
167	                finDelGrupo, [], SinRelleno, VocabularioAgregados.VerbosDeExistencia))
168	            .Any(finDelVerbo => EsExistenciaDeEstado(frases, finDelVerbo));
169	
170	    private static bool EsExistenciaDeEstado(FrasesDelTexto frases, int finDelVerbo) =>
171	        !frases.HayDestinoEnLosSiguientes(finDelVerbo, SinPalabrasEntre, VocabularioAgregados.Derecho)
172	        && frases.HayDestinoEnLosSiguientes(finDelVerbo, MaximoEntreVerboYEstado, VocabularioAgregados.Estados);
173	}
174	namespace TutorFlow.Core.Autorizacion;
175	
176	internal static class ProximidadDeFrases
177	{
178	    public static bool Hay(IEnumerable<OcurrenciaDeFrase> primeras, IReadOnlyCollection<OcurrenciaDeFrase> segundas, int maximoEntre) =>
179	        primeras.Any(primera => Cercanas(primera, segundas, maximoEntre));
180	
181	    public static bool Cercanas(OcurrenciaDeFrase primera, IEnumerable<OcurrenciaDeFrase> segundas, int maximoEntre) =>
182	        segundas.Any(segunda => PalabrasEntre(primera, segunda) is >= 0 and var entre && entre <= maximoEntre);
183	
184	    private static int PalabrasEntre(OcurrenciaDeFrase primera, OcurrenciaDeFrase segunda)
185	    {
186	        if (segunda.Inicio >= primera.Fin)
187	        {
188	            return segunda.Inicio - primera.Fin;
189	        }
190	
191	        return primera.Inicio >= segunda.Fin ? primera.Inicio - segunda.Fin : -1;
192	    }
193	}

