  1	using System.Text;
  2	using System.Text.Json;
  3	using Microsoft.Extensions.Logging;
  4	
  5	namespace TutorFlow.Infrastructure.Llm;
  6	
  7	public static partial class DiagnosticoDelProveedor
  8	{
  9	    public const int LongitudMaximaDelCodigo = 64;
 10	    private static readonly string[] CamposDeCodigo = ["status", "code", "type"];
 11	
 12	    public static void Registrar(ILogger? logger, int estado, string? cuerpo)
 13	    {
 14	        if (logger is null)
 15	        {
 16	            return;
 17	        }
 18	
 19	        var codigo = CodigoDe(cuerpo);
 20	        if (codigo.Length == 0)
 21	        {
 22	            RegistrarSoloEstado(logger, estado);
 23	            return;
 24	        }
 25	
 26	        RegistrarConCodigo(logger, estado, codigo);
 27	    }
 28	
 29	    public static string CodigoDe(string? cuerpo)
 30	    {
 31	        if (string.IsNullOrWhiteSpace(cuerpo))
 32	        {
 33	            return string.Empty;
 34	        }
 35	
 36	        try
 37	        {
 38	            using var documento = JsonDocument.Parse(cuerpo);
 39	            return PrimerCodigo(documento.RootElement);
 40	        }
 41	        catch (JsonException)
 42	        {
 43	            return string.Empty;
 44	        }
 45	    }
 46	
 47	    private static string PrimerCodigo(JsonElement raiz) =>
 48	        ObjetoError(raiz) is { } error
 49	            ? CamposDeCodigo.Select(campo => TextoDe(error, campo)).FirstOrDefault(texto => texto.Length > 0) ?? string.Empty
 50	            : string.Empty;
 51	
 52	    private static JsonElement? ObjetoError(JsonElement raiz) =>
 53	        raiz.ValueKind == JsonValueKind.Object && raiz.TryGetProperty("error", out var error) && error.ValueKind == JsonValueKind.Object
 54	            ? error
 55	            : null;
 56	
 57	    private static string TextoDe(JsonElement error, string campo) =>
 58	        error.TryGetProperty(campo, out var valor) ? Sanear(Texto(valor) ?? string.Empty) : string.Empty;
 59	
 60	    private static string? Texto(JsonElement valor) => valor.ValueKind switch
 61	    {
 62	        JsonValueKind.String => valor.GetString(),
 63	        JsonValueKind.Number => valor.GetRawText(),
 64	        _ => null
 65	    };
 66	
 67	    private static string Sanear(string texto)
 68	    {
 69	        var permitido = new StringBuilder();
 70	        foreach (var caracter in texto.Where(EsPermitido).Take(LongitudMaximaDelCodigo))
 71	        {
 72	            permitido.Append(caracter);
 73	        }
 74	
 75	        return permitido.ToString();
 76	    }
 77	
 78	    private static bool EsPermitido(char caracter) =>
 79	        char.IsAsciiLetterOrDigit(caracter) || caracter is '_' or '.' or '-';
 80	
 81	    [LoggerMessage(Level = LogLevel.Warning, Message = "El proveedor del LLM respondió con error {Estado}.")]
 82	    private static partial void RegistrarSoloEstado(ILogger logger, int estado);
 83	
 84	    [LoggerMessage(Level = LogLevel.Warning, Message = "El proveedor del LLM respondió con error {Estado} {Codigo}.")]
 85	    private static partial void RegistrarConCodigo(ILogger logger, int estado, string codigo);
 86	}
 87	using System.ClientModel.Primitives;
 88	using System.Text.Json;
 89	using System.Text.Json.Nodes;
 90	using Microsoft.Extensions.AI;
 91	using OpenAI.Chat;
 92	using ChatMessage = Microsoft.Extensions.AI.ChatMessage;
 93	using TutorFlow.Core.Asistente;
 94	
 95	namespace TutorFlow.Infrastructure.Llm;
 96	
 97	internal static class LlamadasConDatoOpaco
 98	{
 99	    private static readonly HashSet<string> PropiedadesConocidas = ["id", "type", "function"];
100	
101	    public static LlamadaHerramienta Traducir(FunctionCallContent llamada) =>
102	        new(
103	            llamada.CallId,
104	            llamada.Name,
105	            JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>()),
106	            llamada.RawRepresentation is ChatToolCall cruda && TraeDatoAdicional(cruda) ? new DatoOpacoDelProveedor(cruda) : null);
107	
108	    private static bool TraeDatoAdicional(ChatToolCall cruda)
109	    {
110	        using var documento = JsonDocument.Parse(ModelReaderWriter.Write(cruda));
111	        return documento.RootElement.EnumerateObject().Any(propiedad => !PropiedadesConocidas.Contains(propiedad.Name));
112	    }
113	
114	    public static ChatMessage ConDatoOpaco(ChatMessage reconstruido, MensajeLlm mensaje)
115	    {
116	        if (mensaje.Llamadas.Count > 0 && mensaje.Llamadas.All(Coincide))
117	        {
118	            reconstruido.RawRepresentation = MensajeCrudo(mensaje);
119	        }
120	
121	        return reconstruido;
122	    }
123	
124	    private static AssistantChatMessage MensajeCrudo(MensajeLlm mensaje)
125	    {
126	        var crudo = new AssistantChatMessage(mensaje.Llamadas.Select(llamada => (ChatToolCall)llamada.DatoOpaco!.Valor));
127	        if (!string.IsNullOrEmpty(mensaje.Contenido))
128	        {
129	            crudo.Content.Add(ChatMessageContentPart.CreateTextPart(mensaje.Contenido));
130	        }
131	
132	        return crudo;
133	    }
134	
135	    private static bool Coincide(LlamadaHerramienta llamada) =>
136	        llamada.DatoOpaco?.Valor is ChatToolCall cruda
137	        && cruda.Id == llamada.Id
138	        && cruda.FunctionName == llamada.Nombre
139	        && MismosArgumentos(cruda.FunctionArguments, llamada.ArgumentosJson);
140	
141	    private static bool MismosArgumentos(BinaryData? crudos, string ejecutados)
142	    {
143	        try
144	        {
145	            return JsonNode.DeepEquals(JsonNode.Parse(crudos?.ToString() ?? "{}"), JsonNode.Parse(ejecutados));
146	        }
147	        catch (JsonException)
148	        {
149	            return false;
150	        }
151	    }
152	}

