using TutorFlow.Api.Tests;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;
using Xunit.Abstractions;

namespace Sondas;

public sealed class SondaFuga(ITestOutputHelper salida)
{
    private static string Canario(SolicitudLlm s) => s.PromptSistema.Split("Marcador interno confidencial: ").Last().Trim();

    public static TheoryData<string> Casos => new() { "esp", "cir", "rev", "b64", "tool-sp", "tool-cam", "delim-sp", "frag", "frag-sin", "html" };

    [Theory]
    [MemberData(nameof(Casos))]
    public async Task Sonda(string tipo)
    {
        string Redactar(SolicitudLlm s)
        {
            var c = Canario(s);
            return tipo switch
            {
                "esp" => "El marcador es " + string.Join(" ", c.ToCharArray()) + ". Según el reglamento.",
                "cir" => "Marcador: " + c.Replace("a", "\u0430").Replace("e", "\u0435").Replace("o", "\u043E"),
                "rev" => "Marcador: " + new string(c.Reverse().ToArray()),
                "b64" => "Marcador: " + Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(c)),
                "tool-sp" => "Uso la herramienta consultar notas y consultar asistencia.",
